import React, { useState, useEffect, useRef } from "react";
import "./brutalist-button.css";

export default function ValentineApp() {
    const [page, setPage] = useState("home");
    const [userName, setUserName] = useState("");
    const [selectedColor, setSelectedColor] = useState("");

    return (
        <div className="valentine-container">

            {/* Floating Hearts */}
            <div className="wrapper">
                <div className="heart x1"></div>
                <div className="heart x2"></div>
                <div className="heart x3"></div>
                <div className="heart x4"></div>
                <div className="heart x5"></div>
                <div className="altheart x6"></div>
            </div>

            {/* Routing */}
            {page === "home" && <HomePage onYes={() => setPage("game")} />}
            {page === "game" && <DinoGamePage onFinish={() => setPage("input")} />}

            {page === "input" && (
                <InputPage
                    userName={userName}
                    setUserName={setUserName}
                    selectedColor={selectedColor}
                    setSelectedColor={setSelectedColor}
                    onSubmit={() => setPage("final")}
                />
            )}

            {page === "final" && (
                <FinalPage
                    userName={userName}
                    selectedColor={selectedColor}
                />
            )}

            {/* Styles */}
            <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@400;600;700&display=swap');

        * {
          margin: 0;
          padding: 0;
          box-sizing: border-box;
        }

        body {
          font-family: 'Quicksand', sans-serif;
        }

        .valentine-container {
          min-height: 100vh;
          background: linear-gradient(135deg,#FFE5EC,#FFCDB2,#E4C1F9);
          position: relative;
          overflow: hidden;
        }

        /* Floating Hearts */

        .wrapper {
          position: fixed;
          inset: 0;
          overflow: hidden;
          pointer-events: none;
          z-index: 1;
        }

        .heart,
        .altheart {
          position: absolute;
          bottom: -100px;
        }

        .x1 {
          left: 5%;
          transform: scale(0.9);
          opacity: 0.6;
          animation: move 15s linear infinite, side 4s ease-in-out infinite alternate;
        }

        .x2 {
          left: 25%;
          transform: scale(0.6);
          opacity: 0.9;
          animation: move 25s linear infinite, side 5s ease-in-out infinite alternate;
        }

        .x3 {
          left: 55%;
          transform: scale(0.8);
          opacity: 0.8;
          animation: move 20s linear infinite, side 4s ease-in-out infinite alternate;
        }

        .x4 {
          left: 72%;
          transform: scale(0.75);
          opacity: 0.9;
          animation: move 18s linear infinite, side 2s ease-in-out infinite alternate;
        }

        .x5 {
          left: 88%;
          transform: scale(0.8);
          opacity: 0.3;
          animation: move 12s linear infinite, side 2s ease-in-out infinite alternate;
        }

        .x6 {
          left: 33%;
          animation: move 10s linear infinite, sway 6s ease-in-out infinite alternate;
        }

        @keyframes move {
          from { top: 100%; }
          to { top: -200px; }
        }

        @keyframes side {
          from { margin-left: 0; }
          to { margin-left: 50px; }
        }

        @keyframes sway {
          0% { transform: rotate(12deg); }
          50% { transform: rotate(-5deg); }
          100% { transform: rotate(0deg); }
        }

        .heart:before,
        .heart:after {
          content: "";
          position: absolute;
          width: 18px;
          height: 30px;
          background: #ff4d6d;
          border-radius: 30px 30px 0 0;
        }

        .heart:before {
          left: 18px;
          transform: rotate(-45deg);
          transform-origin: 0 100%;
        }

        .heart:after {
          left: 0;
          transform: rotate(45deg);
          transform-origin: 100% 100%;
        }

        .altheart {
          background: url("https://static.indigoimages.ca/2016/shop/113439_img25_twotoneheart.png") no-repeat center/contain;
          width: 24px;
          height: 21px;
        }

        /* Home Page */

        .home-page {
          min-height: 100vh;
          display: flex;
          flex-direction: column;
          justify-content: center;
          align-items: center;
          gap: 40px;
          z-index: 2;
          position: relative;
          text-align: center;
        }

        .title {
          font-family: 'Pacifico', cursive;
          font-size: clamp(2.5rem,6vw,4rem);
          color: #ff6b9d;
        }

        /* Game */

        .game-page {
          min-height: 100vh;
          display: flex;
          flex-direction: column;
          justify-content: center;
          align-items: center;
          gap: 20px;
          z-index: 2;
          position: relative;
          padding: 20px;
        }

        .game-container {
          background: white;
          border-radius: 20px;
          padding: 30px;
          box-shadow: 0 20px 40px rgba(255,107,157,.3);
        }

        .game-title {
          font-family: 'Pacifico', cursive;
          color: #ff6b9d;
          margin-bottom: 20px;
          text-align: center;
        }

        .game-box {
          width: 600px;
          max-width: 90vw;
          height: 200px;
          border: 3px solid #ff6b9d;
          border-radius: 15px;
          background: #f0f0f0;
          position: relative;
          overflow: hidden;
        }

        .game-ground {
          position: absolute;
          bottom: 0;
          width: 100%;
          height: 200px;
          background-size: cover;
          background-repeat: repeat-x;
          background-position: bottom;
        }

        .game-dino {
          position: absolute;
          left: 50px;
          bottom: 0;
          width: 50px;
          height: 50px;
          background-size: contain;
          background-repeat: no-repeat;
          transition: bottom 0.1s;
          z-index: 10;
        }

        .game-obstacle {
          position: absolute;
          bottom: 0;
          width: 40px;
          height: 50px;
          background-size: contain;
          background-repeat: no-repeat;
          z-index: 5;
        }

        .game-alert {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%);
          font-family: 'Pacifico', cursive;
          font-size: 2rem;
          color: #ff6b9d;
          text-shadow: 2px 2px 4px rgba(0,0,0,0.1);
          z-index: 20;
        }

        .game-instructions {
          text-align: center;
          margin: 15px 0;
          color: #666;
        }

        .game-score {
          text-align: center;
          font-weight: bold;
          color: #ff6b9d;
          margin-bottom: 10px;
        }

        /* Input */

        .input-page {
          min-height: 100vh;
          display: flex;
          justify-content: center;
          align-items: center;
          z-index: 2;
          padding: 20px;
        }

        .input-card {
          background: #fff;
          padding: 40px;
          border-radius: 25px;
          width: 100%;
          max-width: 450px;
          box-shadow: 0 20px 40px rgba(255,107,157,.3);
        }

        .input-title {
          font-family: 'Pacifico';
          text-align: center;
          margin-bottom: 30px;
          color: #ff6b9d;
        }

        .text-input {
          width: 100%;
          padding: 14px;
          border-radius: 12px;
          border: 2px solid #ffb3c6;
          margin-top: 8px;
          font-family: 'Quicksand', sans-serif;
        }

        .submit-button {
          width: 100%;
          margin-top: 25px;
          padding: 14px;
          background: #ff6b9d;
          border: none;
          color: #fff;
          border-radius: 40px;
          font-weight: 700;
          cursor: pointer;
          font-family: 'Quicksand', sans-serif;
          transition: transform 0.2s;
        }

        .submit-button:hover:not(:disabled) {
          transform: scale(1.05);
        }

        .submit-button:disabled {
          opacity: 0.5;
          cursor: not-allowed;
        }

        /* Final */

        .final-page {
          min-height: 100vh;
          display: flex;
          flex-direction: column;
          justify-content: center;
          align-items: center;
          text-align: center;
          z-index: 2;
          gap: 20px;
        }

        .final-message {
          font-family: 'Pacifico';
          color: #ff6b9d;
          font-size: 2.5rem;
        }
      `}</style>

        </div>
    );
}

/* HOME */

function HomePage({ onYes }) {

    const [pos, setPos] = useState({ x: 0, y: 0 });
    const [moved, setMoved] = useState(false);

    const move = () => {
        const x = Math.random() * (window.innerWidth - 200);
        const y = Math.random() * (window.innerHeight - 100);

        setPos({ x, y });
        setMoved(true);
    };

    return (
        <div className="home-page">

            <h1 className="title">Will you be my Valentine? 💝</h1>

            {/* YES */}
            <button
                className="brutalist-button button-1 yes-brutal"
                onClick={onYes}
            >
                YES 💖
            </button>

            {/* NO */}
            <button
                className="brutalist-button button-1 no-brutal"
                onMouseEnter={move}
                onClick={move}
                onTouchStart={move}
                style={
                    moved
                        ? { left: pos.x, top: pos.y, position: "absolute" }
                        : { position: "relative" }
                }
            >
                NO 😜
            </button>

        </div>
    );
}

/* DINO GAME */

function DinoGamePage({ onFinish }) {
    const [isJumping, setIsJumping] = useState(false);
    const [isGameOver, setIsGameOver] = useState(false);
    const [score, setScore] = useState(0);
    const [dinoBottom, setDinoBottom] = useState(0);
    const [obstacles, setObstacles] = useState([]);

    const gameRef = useRef(null);
    const animationRef = useRef(null);
    const obstacleIdRef = useRef(0);

    // Convert uploaded images to base64 data URLs
    const cactiImage = "data:cacti/png;base64,";

    const desertImage = "data:desert/png;base64,";

    const charImage = "data:char/png;base64,";

    // Jump function
    const jump = () => {
        if (isJumping || isGameOver) return;

        setIsJumping(true);
        let position = 0;
        let count = 0;
        const gravity = 0.9;

        const upInterval = setInterval(() => {
            if (count === 15) {
                clearInterval(upInterval);

                const downInterval = setInterval(() => {
                    if (count === 0) {
                        clearInterval(downInterval);
                        setIsJumping(false);
                        setDinoBottom(0);
                    }
                    position -= 5;
                    count--;
                    position = position * gravity;
                    setDinoBottom(Math.max(0, position));
                }, 20);
            }

            position += 30;
            count++;
            position = position * gravity;
            setDinoBottom(position);
        }, 20);
    };

    // Handle keyboard and touch controls
    useEffect(() => {
        const handleKeyPress = (e) => {
            if (e.code === "Space" || e.key === " ") {
                e.preventDefault();
                jump();
            }
        };

        const handleClick = () => {
            jump();
        };

        document.addEventListener('keydown', handleKeyPress);
        if (gameRef.current) {
            gameRef.current.addEventListener('click', handleClick);
            gameRef.current.addEventListener('touchstart', handleClick);
        }

        return () => {
            document.removeEventListener('keydown', handleKeyPress);
            if (gameRef.current) {
                gameRef.current.removeEventListener('click', handleClick);
                gameRef.current.removeEventListener('touchstart', handleClick);
            }
        };
    }, [isJumping, isGameOver]);

    // Generate obstacles
    useEffect(() => {
        if (isGameOver) return;

        const generateObstacle = () => {
            if (isGameOver) return;

            const id = obstacleIdRef.current++;
            const newObstacle = {
                id,
                position: 600
            };

            setObstacles(prev => [...prev, newObstacle]);

            const randomTime = Math.random() * 3000 + 2000;
            setTimeout(generateObstacle, randomTime);
        };

        const timeout = setTimeout(generateObstacle, 2000);

        return () => clearTimeout(timeout);
    }, [isGameOver]);

    // Move obstacles and check collision
    useEffect(() => {
        if (isGameOver) return;

        const interval = setInterval(() => {
            setObstacles(prev => {
                return prev.map(obstacle => {
                    const newPosition = obstacle.position - 5;

                    // Check collision
                    if (newPosition > 40 && newPosition < 90 && dinoBottom < 50) {
                        setIsGameOver(true);
                    }

                    // Increase score when obstacle passes
                    if (newPosition === 40) {
                        setScore(s => s + 1);
                    }

                    return { ...obstacle, position: newPosition };
                }).filter(obstacle => obstacle.position > -50);
            });
        }, 20);

        return () => clearInterval(interval);
    }, [isGameOver, dinoBottom]);

    const resetGame = () => {
        setIsGameOver(false);
        setScore(0);
        setDinoBottom(0);
        setObstacles([]);
        obstacleIdRef.current = 0;
    };

    return (
        <div className="game-page">
            <div className="game-container">
                <h2 className="game-title">🦖 Dino Love Run 💖</h2>

                <div className="game-score">Score: {score}</div>

                <div className="game-instructions">
                    Press SPACE or Click/Tap to Jump!
                </div>

                <div className="game-box" ref={gameRef}>
                    <div
                        className="game-ground"
                        style={{
                            backgroundImage: `url(${desertImage})`
                        }}
                    />

                    <div
                        className="game-dino"
                        style={{
                            bottom: `${dinoBottom}px`,
                            backgroundImage: `url(${charImage})`
                        }}
                    />

                    {obstacles.map(obstacle => (
                        <div
                            key={obstacle.id}
                            className="game-obstacle"
                            style={{
                                left: `${obstacle.position}px`,
                                backgroundImage: `url(${cactiImage})`
                            }}
                        />
                    ))}

                    {isGameOver && (
                        <div className="game-alert">
                            Game Over! 💔<br/>
                            <small style={{fontSize: '1rem'}}>Score: {score}</small>
                        </div>
                    )}
                </div>

                {isGameOver ? (
                    <div style={{display: 'flex', gap: '10px', marginTop: '20px'}}>
                        <button
                            className="submit-button"
                            onClick={resetGame}
                            style={{width: 'auto', padding: '12px 30px'}}
                        >
                            Try Again 🔄
                        </button>
                        <button
                            className="submit-button"
                            onClick={onFinish}
                            style={{width: 'auto', padding: '12px 30px'}}
                        >
                            Continue 💖
                        </button>
                    </div>
                ) : (
                    <button
                        className="submit-button"
                        onClick={onFinish}
                        style={{marginTop: '20px'}}
                    >
                        Skip Game ➡️
                    </button>
                )}
            </div>
        </div>
    );
}

/* INPUT */

function InputPage({
                       userName,
                       setUserName,
                       selectedColor,
                       setSelectedColor,
                       onSubmit,
                   }) {

    const colors = ["Pink", "Peach", "Lavender", "Mint", "Coral", "Blue"];

    return (
        <div className="input-page">

            <div className="input-card">

                <h2 className="input-title">Tell me about you 💕</h2>

                <label>Name</label>
                <input
                    className="text-input"
                    value={userName}
                    onChange={(e) => setUserName(e.target.value)}
                    placeholder="Enter your name"
                />

                <label style={{ marginTop: "15px" }}>Favorite Color</label>

                <select
                    className="text-input"
                    value={selectedColor}
                    onChange={(e) => setSelectedColor(e.target.value)}
                >
                    <option value="">Choose a color</option>

                    {colors.map(c => (
                        <option key={c}>{c}</option>
                    ))}

                </select>

                <button
                    className="submit-button"
                    disabled={!userName || !selectedColor}
                    onClick={onSubmit}
                >
                    Submit 💌
                </button>

            </div>

        </div>
    );
}

/* FINAL */

function FinalPage({ userName, selectedColor }) {

    return (
        <div className="final-page">

            <h1 className="final-message">
                Thank You {userName}! 💖
            </h1>

            <p style={{fontSize: '1.2rem', color: '#666'}}>
                You chose {selectedColor} 🌸
            </p>

            <div style={{ fontSize: "4rem", margin: '20px 0' }}>🎁</div>

            <p style={{fontSize: '1.5rem', fontFamily: 'Pacifico', color: '#ff6b9d'}}>
                Happy Valentine's Day! 💝
            </p>

        </div>
    );
}
